import math

def centered(v):
    m=sum(v)/len(v); return [x-m for x in v]
def pairs(v):
    return {(i,j):v[i]-v[j] for i in range(len(v)) for j in range(len(v)) if i!=j}
def loss(c,r):
    return sum(((c[i]-c[j])-x)**2 for (i,j),x in r.items())
def qhat(scores,a):
    rank=math.ceil((len(scores)+1)*(1-a)); return (math.inf if rank>len(scores) else sorted(scores)[rank-1]),rank
def decide(b,c,w,q):
    D={}; lows=[]
    for i in range(len(b)):
        li=[]
        for j in range(len(b)):
            if i==j: continue
            ctr=(b[i]-b[j])+(c[i]-c[j]); D[i,j]=(ctr-w-q,ctr+w+q); li.append(D[i,j][0])
        lows.append(min(li))
    M=max(lows); win=max(range(len(b)),key=lambda i:(lows[i],-i)); return D,lows,M,win if M>0 else None
s0=[.55,.45,.25]; Y=[0.,1.,0.]; u=[y-s for y,s in zip(Y,s0)]; c=centered(u); r=pairs(u)
print('u_direct=',[round(x,6) for x in u]); print('c_direct_centered=',[round(x,6) for x in c],'mean=',round(sum(c)/len(c),12))
print('max_pair_equivalence_error=',max(abs(r[i,j]-(c[i]-c[j])) for i,j in r)); print('pair_loss_if_e=-7=',loss(c,r)); print('pair_loss_if_e=+11=',loss(c,r))
scores=[.01,.02,.025,.03,.035,.04,.045,.05,.055,.06,.065,.07,.075,.08,.085,.09,.095,.10,.11,.12]; q,rank=qhat(scores,.10); print('q_rank=',rank,'q_alpha=',q)
D,L,M,W=decide(s0,[-.05,.10,-.05],.03,q); D2,L2,M2,W2=decide(s0,[-.05,.10,-.05],.03,q); print('D01=',tuple(round(x,6) for x in D[0,1])); print('lower_by_candidate=',[round(x,6) for x in L],'M_t=',round(M,6),'selected=',W); print('direct_vs_quotient_same_intervals=',D2==D); print('direct_vs_quotient_same_M=',M2==M,'same_selected=',W2==W)
b=[.95,.05]; cb=[.20,-.20]; clip=[min(1,max(0,x+y)) for x,y in zip(b,cb)]; print('clipped_difference=',clip[0]-clip[1],'unclipped_D_center=',(b[0]-b[1])+(cb[0]-cb[1]),'mismatch=',(b[0]-b[1])+(cb[0]-cb[1])-(clip[0]-clip[1]))
for label,base,cor in [('K1',[.5],[0.]),('K0',[],[])]:
    try: decide(base,cor,.03,q)
    except ValueError as ex: print(label,type(ex).__name__,str(ex))
